import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage }) {
  const menuItems = [
    { name: 'Overview', icon: '👁️‍🗨️' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  return (
    <div style={{
      width: '260px',
      backgroundColor: '#15803d',
      color: '#fff',
      display: 'flex',
      flexDirection: 'column',
      height: '100vh',
      padding: '20px 10px'
    }}>
      
      <div style={{ padding: '10px 15px', fontWeight: 'bold', fontSize: '18px' }}>
        📌 Admin Panel
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', marginTop: '20px', gap: '6px' }}>
        {menuItems.map((item, i) => {
          const active = currentSubPage === item.name;

          return (
            <div
              key={i}
              onClick={() => setCurrentSubPage(item.name)}
              style={{
                padding: '14px 16px',
                borderRadius: '8px',
                cursor: 'pointer',
                backgroundColor: active ? '#166534' : 'transparent',
                display: 'flex',
                gap: '10px',
                alignItems: 'center'
              }}
            >
              <span>{item.icon}</span>
              <span>{item.name}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}
